{
  "missing_information": [
    {
      "category": "Tool Selection Criteria",
      "gap": "No information on how or why a specific measurement tool is chosen for a given wafer",
      "why_it_matters": "Without knowing the selection logic, it is impossible to determine whether tool assignment can be automated or optimized"
    },
    {
      "category": "Preparation Steps per Tool",
      "gap": "The specific preparation steps required before measurement for each tool are not described",
      "why_it_matters": "Preparation steps vary by tool and may include manual, semi-automated, or fully automated sub-processes that affect automation potential"
    },
    {
      "category": "Measurement Step Details",
      "gap": "The actual measurement procedure for each tool is not specified, including duration, operator involvement, and parameter settings",
      "why_it_matters": "Understanding operator involvement and parameter configuration is essential to assess which steps can be automated"
    },
    {
      "category": "Result Recording Method",
      "gap": "It is unclear how the engineer records the measurement result, whether via manual entry, system integration, or automated data capture",
      "why_it_matters": "The recording method directly determines automation feasibility and data quality risks"
    },
    {
      "category": "Exception Handling",
      "gap": "No information is provided about what happens when a measurement fails, a tool is unavailable, or results fall outside acceptable ranges",
      "why_it_matters": "Exception paths are critical for complete process reconstruction and for assessing robustness of any automated solution"
    },
    {
      "category": "Downstream Process Triggers",
      "gap": "It is not described what happens after the result is recorded, including who receives it, what decisions are made, or what process is triggered next",
      "why_it_matters": "Without knowing downstream dependencies, the end-to-end process cannot be reconstructed and handoff automation cannot be evaluated"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What criteria determine which measurement tool is selected for a given wafer, and is this selection made by a person, a rule, or a system?",
      "targets": ["Tool Selection Criteria"]
    },
    {
      "id": "Q2",
      "question": "Can you walk through the preparation steps required before measurement for each tool type, noting which steps differ across tools?",
      "targets": ["Preparation Steps per Tool"]
    },
    {
      "id": "Q3",
      "question": "During the measurement step itself, what actions does the operator perform, and to what extent does the tool operate autonomously versus requiring manual input?",
      "targets": ["Measurement Step Details"]
    },
    {
      "id": "Q4",
      "question": "How does the engineer record the measurement result — for example, is it entered manually into a form or system, or is it captured automatically from the tool?",
      "targets": ["Result Recording Method"]
    },
    {
      "id": "Q5",
      "question": "What happens if a measurement result is out of specification or if a tool becomes unavailable mid-process — is there a defined fallback or escalation procedure?",
      "targets": ["Exception Handling"]
    },
    {
      "id": "Q6",
      "question": "After the measurement result is recorded, what is the next step in the process and who or what system consumes that result?",
      "targets": ["Downstream Process Triggers"]
    }
  ]
}
